// Lleva todas las fuentes a un mismo formato: fuente, título, link, fecha, resumen.
const HOST_A_FUENTE = {
  'blog.n8n.io': 'n8n blog',
  'community.n8n.io': 'n8n foro',
  'openai.com': 'OpenAI',
  'blog.google': 'Google AI',
  'www.producthunt.com': 'Product Hunt',
  'www.reddit.com': 'Reddit'
};

const limpiarHtml = s => String(s || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.error || !j.link || !j.title) continue;   // fuente caída o item incompleto

  const link = String(j.link);
  const host = (link.match(/^https?:\/\/([^\/?#]+)/i) || [])[1]?.toLowerCase() || '';
  let fuente = j._fuente || HOST_A_FUENTE[host] || host || 'otra';

  if (!j._fuente && host === 'github.com') {
    if (link.includes('/n8n-io/n8n/')) fuente = 'n8n releases';
    else if (link.includes('/anthropics/claude-code/')) fuente = 'Claude Code releases';
  }

  let resumen = String(j.contentSnippet || '') || limpiarHtml(j.content || j.summary || j.description);
  resumen = resumen
    .replace(/submitted by\s+\/u\/\S+\s*\[link\]\s*\[comments\]/i, '')
    .replace(/Discussion\s*\|\s*Link/i, '')
    .trim();

  salida.push({ json: {
    fuente,
    titulo: j.title,
    link,
    carril: j._carril || 'principal',
    fecha: j.isoDate || j.pubDate || null,
    categoria: [].concat(j.categories || j.category || []).map(String).join(', '),
    resumen: resumen.slice(0, 400)
  }});
}
return salida;

// Descarta lo viejo, los releases que no son versiones y los títulos repetidos.
const cfg = $('Configuración').first().json;
const DIAS = Number(cfg.dias_hacia_atras) || 3;
const DIAS_RAPIDAS = 2;                       // foros y agregadores se renuevan rápido
const RAPIDAS = ['n8n foro', 'Reddit automation', 'Product Hunt', 'Hacker News'];
const FORO_OK = ['built with n8n', 'tips & tricks'];

const ahora = Date.now();
const vistos = new Set();
const salida = [];

for (const item of $input.all()) {
  const j = item.json;
  const t = Date.parse(j.fecha);
  if (isNaN(t)) continue;
  const dias = RAPIDAS.includes(j.fuente) ? DIAS_RAPIDAS : DIAS;
  if (t < ahora - dias * 24 * 3600 * 1000) continue;

  if (j.fuente === 'n8n releases' && !String(j.titulo).startsWith('n8n@')) continue;
  if (j.fuente === 'n8n foro' && j.categoria) {
    const cat = j.categoria.replace(/&amp;/g, '&').toLowerCase();
    if (!FORO_OK.some(c => cat.includes(c))) continue;
  }

  const clave = String(j.titulo).trim().toLowerCase();
  if (vistos.has(clave)) continue;
  vistos.add(clave);
  salida.push(item);
}
salida.sort((a, b) => Date.parse(b.json.fecha) - Date.parse(a.json.fecha));
return salida.length ? salida : [{ json: { vacio: true } }];

// Puntúa cada noticia con reglas simples ANTES de llamar a la IA:
// así el modelo recibe una lista corta y el costo por ejecución queda bajo.
const cfg = $('Configuración').first().json;

const MAX_POR_FUENTE = { 'n8n releases': 2, 'Claude Code releases': 2, 'OpenAI': 4, 'n8n blog': 3, 'Google AI': 2, 'n8n foro': 6, 'Product Hunt': 3 };
const TOTAL_PRINCIPAL = 12;
const MAX_POR_FUENTE_EXTRA = { 'Simon Willison': 2, 'Hacker News': 3, 'Hugging Face': 2, 'MIT Tech Review': 2, 'Quanta': 1, 'The Verge AI': 2, 'Reddit automation': 2 };
const TOTAL_EXTRA = 8;

const aRegex = lista => {
  const palabras = String(lista || '').split(',').map(p => p.trim()).filter(Boolean)
    .map(p => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  return palabras.length ? new RegExp(palabras.join('|'), 'i') : null;
};
const SUMAN = aRegex(cfg.palabras_que_suman);
const RESTAN = aRegex(cfg.palabras_que_restan);
const SPAM = /disclosure|i['’]?m the founder|we run a|for hire|beta testers|free templates|looking for|need help/i;
const CAMBIOS = /deprecat|pricing|shut ?down|sunset|breaking/i;

function puntaje(j) {
  const t = `${j.titulo} ${j.resumen}`;
  let p = 0;
  if (SUMAN && SUMAN.test(t)) p += 2;
  if (CAMBIOS.test(t)) p += 3;
  if (RESTAN && RESTAN.test(t)) p -= 5;
  if (SPAM.test(t)) p -= 4;
  return p;
}

const porFecha = (a, b) => Date.parse(b.fecha) - Date.parse(a.fecha);
const orden = (a, b) => b.p - a.p || porFecha(a, b);

const principal = {}, extra = {};
for (const item of $input.all()) {
  const j = item.json;
  if (j.carril === 'extra') { (extra[j.fuente] = extra[j.fuente] || []).push(j); continue; }
  const p = puntaje(j);
  if (p < 0) continue;
  (principal[j.fuente] = principal[j.fuente] || []).push({ ...j, p });
}

let lista = [];
for (const f of Object.keys(principal)) {
  principal[f].sort(orden);
  lista.push(...principal[f].slice(0, MAX_POR_FUENTE[f] ?? 3));
}
lista = lista.sort(orden).slice(0, TOTAL_PRINCIPAL);

let ampliar = [];
for (const f of Object.keys(extra)) {
  extra[f].sort(porFecha);
  ampliar.push(...extra[f].slice(0, MAX_POR_FUENTE_EXTRA[f] ?? 2));
}
ampliar = ampliar.sort(porFecha).slice(0, TOTAL_EXTRA).map(j => ({ ...j, p: 0 }));

const todo = [...lista, ...ampliar];
const texto = todo.map((j, i) =>
  `[${i + 1}] (${j.carril === 'extra' ? 'EXTRA · ' : ''}${j.fuente}) ${j.titulo} — ${String(j.resumen).replace(/\s+/g, ' ').slice(0, 300)}`
).join('\n');

return [{ json: { items: todo, texto } }];

// Lee la respuesta de la IA, valida el JSON y arma la selección final.
const cfg = $('Configuración').first().json;
const lista = $('Puntuar y armar prompt').first().json.items;
const r = $input.first().json;

let texto = r.output?.[0]?.content?.[0]?.text ?? r.message?.content ?? r.text ?? r.output ?? '';
if (typeof texto !== 'string') texto = JSON.stringify(texto);
texto = texto.replace(/```json|```/g, '').trim();

let arr = [];
try {
  arr = JSON.parse(texto).items || [];
} catch (e) {
  // Si el modelo no devuelve JSON válido, no se rompe: se avisa por mail.
  return [{ json: { error: 'El modelo no devolvió un JSON válido', crudo: texto.slice(0, 500) } }];
}

const PRINCIPALES = ['ACCION', 'IDEA', 'TENDENCIA', 'COMPETENCIA'];
const EXTRAS = ['IA', 'CIENCIA_TECH', 'IDEA_FLUJO', 'HERRAMIENTAS'];
const MAX_PRINC = Number(cfg.max_principales) || 6;
const MAX_EXTRA = Number(cfg.max_extra) || 5;
const MAX_POR_FUENTE_EXTRA = 2;

const princ = [], extra = [], usados = new Set();
for (const s of arr) {
  const j = lista[s.n - 1];
  if (!j || usados.has(s.n)) continue;
  usados.add(s.n);
  const item = { ...j, tipo: s.tipo, por_que: s.por_que };
  if (PRINCIPALES.includes(s.tipo)) princ.push(item);
  else if (EXTRAS.includes(s.tipo)) extra.push(item);
}

princ.sort((a, b) => (b.p || 0) - (a.p || 0) || Date.parse(b.fecha) - Date.parse(a.fecha));
extra.sort((a, b) => Date.parse(b.fecha) - Date.parse(a.fecha));

const cuenta = {};
const extraFinal = extra.filter(j => (cuenta[j.fuente] = (cuenta[j.fuente] || 0) + 1) <= MAX_POR_FUENTE_EXTRA);

const final = [...princ.slice(0, MAX_PRINC), ...extraFinal.slice(0, MAX_EXTRA)];
return final.length ? final.map(j => ({ json: j })) : [{ json: { vacio: true } }];

// Arma el mail en HTML, agrupado por tipo de noticia.
const items = $input.all().map(i => i.json).filter(j => !j.vacio);

if (items.length && items[0].error) {
  return [{ json: {
    subject: 'Resumen de novedades: falló la clasificación',
    html: `<p>El modelo no devolvió un JSON válido.</p><pre>${String(items[0].crudo || '')}</pre>`
  }}];
}

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const fecha = new Date().toLocaleDateString('es-AR', {
  timeZone: 'America/Argentina/Buenos_Aires',
  day: '2-digit', month: '2-digit', year: 'numeric'
});

const BLOQUES = [
  { titulo: null, secciones: [
    ['ACCION', 'Para revisar'],
    ['IDEA', 'Ideas para armar o vender'],
    ['TENDENCIA', 'Tendencias'],
    ['COMPETENCIA', 'Competencia']
  ]},
  { titulo: 'Para ampliar', secciones: [
    ['IA', 'IA'],
    ['CIENCIA_TECH', 'Ciencia y tecnología'],
    ['IDEA_FLUJO', 'Ideas de flujos'],
    ['HERRAMIENTAS', 'Herramientas']
  ]}
];

let html = `<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#222">`;
html += `<h2 style="margin-bottom:4px">Novedades del ${esc(fecha)}</h2>`;

if (!items.length) {
  html += `<p>Hoy no hubo novedades que valgan la pena.</p>`;
} else {
  for (const bloque of BLOQUES) {
    const tipos = bloque.secciones.map(s => s[0]);
    if (!items.some(j => tipos.includes(j.tipo))) continue;
    if (bloque.titulo) {
      html += `<h2 style="margin-top:36px;padding:8px 0;border-top:3px solid #0b57d0">${esc(bloque.titulo)}</h2>`;
    }
    for (const [tipo, titulo] of bloque.secciones) {
      const grupo = items.filter(j => j.tipo === tipo);
      if (!grupo.length) continue;
      html += `<h3 style="border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:24px">${esc(titulo)}</h3>`;
      for (const j of grupo) {
        html += `<p style="margin:12px 0">`;
        html += `<a href="${esc(j.link)}" style="font-weight:bold;color:#0b57d0;text-decoration:none">${esc(j.titulo)}</a><br>`;
        html += `<span style="color:#666;font-size:12px">${esc(j.fuente)}</span><br>`;
        if (j.por_que) html += `<span>${esc(j.por_que)}</span>`;
        html += `</p>`;
      }
    }
  }
}
html += `</div>`;

return [{ json: {
  subject: `Novedades ${fecha}`,
  html,
  cantidad: items.length,
  links: items.map(j => j.link)
}}];

// Saca lo que ya se mandó en los últimos 7 días (según el historial en PostgreSQL).
const enviados = new Set(
  $input.all().map(i => String(i.json.link || '').trim()).filter(Boolean)
);
const nuevos = $('Filtrar recientes y duplicados').all()
  .filter(i => i.json.link && !enviados.has(String(i.json.link).trim()));
return nuevos.length ? nuevos : [{ json: { vacio: true } }];

// Registra todo lo que se evaluó: lo enviado y lo descartado,
// para no volver a procesarlo en los próximos días.
let elegidos = [];
try { elegidos = $('Seleccionar resultados').all(); } catch (e) { return []; }
if (elegidos[0]?.json.error) return [];

const evaluados = $('Puntuar y armar prompt').first().json.items;
const enviados = new Set(elegidos.map(i => i.json.link).filter(Boolean));

return evaluados.map(j => ({ json: {
  link: j.link,
  titulo: j.titulo,
  estado: enviados.has(j.link) ? 'enviado' : 'descartado'
}}));

// Marca las fuentes de interés general para que se clasifiquen aparte.
const FUENTES = ['Simon Willison', 'Hacker News', 'Hugging Face', 'MIT Tech Review', 'Quanta', 'The Verge AI', 'Reddit automation'];
const salida = [];
for (const nodo of FUENTES) {
  let items = [];
  try { items = $(nodo).all(); } catch (e) { continue; }
  for (const it of items) {
    if (it.json.error) continue;
    salida.push({ json: { ...it.json, _fuente: nodo, _carril: 'extra' } });
  }
}
return salida;
